## Why This Is Asked
This question tests mastery of persistent data structures, real-world versioning systems, and memory-time trade-offs. It also probes understanding of shared nodes and functional update semantics.

## Key Concepts
- Fully persistent data structures via path-copying
- Implicit treap or segment tree with augmented sums and sizes
- Version management with O(log n) mutations per update
- Correct boundary handling for empty intervals and edge operations

## Code Example
```javascript
class Node {
  constructor(val, prio, left = null, right = null) {
    this.val = val;
    this.prio = prio;
    this.left = left;
    this.right = right;
    this.size = 1;
    this.sum = val;
  }

  update() {
    this.size = 1 + (this.left?.size ?? 0) + (this.right?.size ?? 0);
    this.sum = this.val + (this.left?.sum ?? 0) + (this.right?.sum ?? 0);
  }
}

function split(root, k) {
  if (!root) return [null, null];
  const leftSize = root.left?.size ?? 0;
  if (k <= leftSize) {
    const [l, r] = split(root.left, k);
    root.left = r;
    root.update();
    return [l, root];
  } else {
    const [l, r] = split(root.right, k - leftSize - 1);
    root.right = l;
    root.update();
    return [root, r];
  }
}

function merge(left, right) {
  if (!left || !right) return left ?? right;
  if (left.prio < right.prio) {
    left.right = merge(left.right, right);
    left.update();
    return left;
  } else {
    right.left = merge(left, right.left);
    right.update();
    return right;
  }
}

function rangeSum(root, l, r) {
  const [, mid] = split(root, l);
  const [target, rest] = split(mid, r - l + 1);
  const result = target?.sum ?? 0;
  return merge(merge(null, target), rest);
}

function insertAt(root, index, val) {
  const [left, right] = split(root, index);
  const newNode = new Node(val, Math.random());
  return merge(merge(left, newNode), right);
}

function eraseAt(root, index) {
  const [left, mid] = split(root, index);
  const [, right] = split(mid, 1);
  return merge(left, right);
}
```

## Why This Is Asked
Autocomplete systems in product search need fast prefix queries with duplicates. A Trie with per-node counts shows practical memory/time trade-offs and handles duplicates transparently.

## Key Concepts
- Trie with endCount and subCount
- Duplicate handling via counts
- O(|word|) insertion/erasure/lookup
- O(|prefix|) prefix query
- Space proportional to total characters stored

## Code Example
```javascript
class Node { constructor(){ this.next = new Map(); this.end=0; this.sub=0; } }
class Trie { constructor(){ this.root=new Node(); }
  insertWord(w){ let cur=this.root; cur.sub++; for(const ch of w){ if(!cur.next.has(ch)) cur.next.set(ch,new Node()); cur=cur.next.get(ch); cur.sub++; } cur.end++; }
  eraseWord(w){ let cur=this.root; cur.sub--; for(const ch of w){ cur=cur.next.get(ch); cur.sub--; } cur.end--; }
  containsWord(w){ let cur=this.root; for(const ch of w){ if(!cur.next.has(ch)) return false; cur=cur.next.get(ch); } return cur.end>0; }
  countWithPrefix(pref){ let cur=this.root; for(const ch of pref){ if(!cur.next.has(ch)) return 0; cur=cur.next.get(ch); } return cur.sub; }
}
```

